 {"name": "AlgebraicGeometry.Scheme.LocalEquations.rescale_coboundary", "kind": "lemma", "signature": "private lemma rescale_coboundary (d : X.LocalEquations) (v : \u2200 x, \u0393(X, d.cover.opens x)\u02e3) (x y : X) : X.unitsRestrict inf_le_left (v x)\u207b\u00b9 * (d.rescale v).ratioUnit x y = d.ratioUnit x y * X.unitsRestrict inf_le_right (v y)\u207b\u00b9", "doc": "The coboundary identity witnessing that rescaling does not change the Picard class: the `0`-cochain `v\u207b\u00b9` conjugates the rescaled cocycle into the original.", "library": "Algebraic-Jacobian-Challenge-Rebuild", "file": "MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian/Picard/DivisorClass.lean", "line": 439}
